    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for perm in [(lst[0] + lst[1]), (lst[1] + lst[0])]:
        if is_balanced(perm):
            return 'Yes'

    return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: Yes
print(match_parens([')', ')']))     # Output: No
